/**
 * generated by stackra gen from src/config/env.config.ts (EnvConfig), runway.yaml
 * (environments.<env>.vars, secrets) — do not edit
 * Purpose: the validated env on both sides. `env` is the public part (`VITE_` fields) parsed from
 *          `import.meta.env` once; Vite inlines it into the browser bundle and the Worker build
 *          alike, so the browser and the Worker read one value (the Sentry DSN included).
 *          `serverEnv(raw)` takes that public part and parses the Worker's bindings (server fields
 *          plus the named secrets) through the same field rules; `createApp` in
 *          `../entry/worker.ts` calls it once per request. A missing or malformed value fails with
 *          a typed error naming the variable.
 * Boundary: validation only; no value is defaulted here. `isDevelopment` comes from the build mode,
 *           so code never reads `import.meta.env` itself.
 * Runtime: isomorphic
 */
import { type BuildFacts, hydrateEnv, type PublicPart } from "@stackra/config";
import { EnvConfig } from "#src/config/env.config";

/**
 * The parsed public env (`analyticsPosthogKey`, `featureFlagsPosthogKey`, `turnstileSiteKey`,
 * `telemetryDsn`) and the build fact `isDevelopment`.
 */
export const env: PublicPart<EnvConfig> & BuildFacts = hydrateEnv(EnvConfig, import.meta.env, {
  only: "public",
});

/**
 * The parsed server env of one request: the inlined public part, then the server fields and the
 * secrets resolved by name from the Worker `env`.
 */
export function serverEnv(raw: unknown): EnvConfig {
  return hydrateEnv(EnvConfig, { ...import.meta.env, ...(raw as Record<string, string>) });
}
